const r = await tools.exec_command({cmd:"python - <<'PY'
import json, pathlib
from zoneinfo import ZoneInfo
import pandas as pd
B=pathlib.Path('/app/dataset')
farms=pd.read_csv(B/'farms.csv'); farms['key']=farms.farm_name.str.strip().str.lower()
reg=pd.read_csv(B/'farm_registry.csv'); meta=reg.merge(farms,on='farm_name')
cal=json.loads((B/'sensors_calibration.json').read_text())['enterprise_platform']['deployment_environments']['system_config']['farms']

def num(x, semi):
 if pd.isna(x): return float('nan')
 s=str(x).strip()
 if semi:
  if ',' in s: s=s.replace('.','').replace(',','.')
 try:return float(s)
 except:return float('nan')

def load(fid):
 p=B/f'production_{fid}.csv'; raw=p.read_bytes(); enc='utf-16' if raw.startswith((b'\xff\xfe',b'\xfe\xff')) else 'utf-8'
 line=raw.decode(enc).splitlines()[3]; semi=line.count(';')>line.count(','); sep=';' if semi else ','
 d=pd.read_csv(p,encoding=enc,skiprows=3,sep=sep,dtype=str)
 d['_row']=range(len(d)); d['_tsraw']=d.iloc[:,0]
 d['_local']=pd.to_datetime(d['_tsraw'],format='mixed',errors='coerce')
 cfg=cal[fid]; vcol=cfg['calibration_data']['value_column_name']; off=cfg['calibration_data']['calibration_offset']
 d['_rec']=d[vcol].map(lambda x:num(x,semi)); d['_true']=d._rec-off
 d['_temp']=d['inverter_temperature_C'].map(lambda x:num(x,semi))
 return d,cfg

for _,m in meta.iterrows():
 fid=m.farm_id; d,cfg=load(fid)
 dup=d[d._local.notna() & d.duplicated('_local',keep=False)].sort_values('_local')
 print('\n',fid,'DUPLICATES',len(dup),'SPIKES',int((d._temp>85).sum()),'badval',d._rec.isna().sum(),'negcorr',int((d._true<0).sum()))
 if len(dup): print(dup[['_row','_tsraw','_temp','_rec','_true']].to_string(index=False))
 sp=d[d._temp>85][['_row','_tsraw','_local','_temp','_true']].sort_values('_local')
 print('spike rows:',sp.to_dict('records'))
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":40000});
