    timezones = _farm_timezones()
    return [
        (row.farm_id.strip(), timezones[row.farm_name.strip().casefold()])
        for row in registry.itertuples(index=False)
    ]


def _number(value: object, uses_decimal_comma: bool) -> float:
    if pd.isna(value):
        return float("nan")

    text = str(value).strip()
    if uses_decimal_comma and "," in text:
        # Locale-formatted exports always include the decimal comma. A bare
        # dot (for example, the injected -999.0 values) remains a decimal dot.
        text = text.replace(".", "").replace(",", ".")
    try:
        return float(text)
    except ValueError:
        return float("nan")


def _read_export(farm_id: str) -> tuple[pd.DataFrame, bool]:
    path = DATASET / f"production_{farm_id}.csv"
    raw = path.read_bytes()
    encoding = "utf-16" if raw.startswith((b"\xff\xfe", b"\xfe\xff")) else "utf-8"
    lines = raw.decode(encoding).splitlines()
    uses_decimal_comma = lines[3].count(";") > lines[3].count(",")
    separator = ";" if uses_decimal_comma else ","
    frame = pd.read_csv(
        path,
        encoding=encoding,
        sep=separator,
        skiprows=3,
        dtype=str,
    )
    return frame, uses_decimal_comma


def _sampling_hours(local_times: pd.Series) -> float:
    differences = (
        local_times.sort_values().diff().dt.total_seconds().div(60).dropna()
    )
    differences = differences[differences > 0]
    if differences.empty:
        return 0.0
    return float(differences.mode().iloc[0]) / 60.0


def _farm_total(farm_id: str, timezone: str, calibration: dict) -> int:
    frame, decimal_comma = _read_export(farm_id)
    timestamp_column = frame.columns[0]
    frame["_local_time"] = pd.to_datetime(
        frame[timestamp_column], format="mixed", errors="coerce"
    )

    # Invalid dates are unusable. Duplicate timestamps are correction records;
    # the later record supersedes the earlier poisoned export value.
    frame = frame.loc[frame["_local_time"].notna()].copy()
    frame = frame.drop_duplicates(subset=["_local_time"], keep="last")
    sampling_hours = _sampling_hours(frame["_local_time"])

    value_config = calibration["calibration_data"]
    value_column = value_config["value_column_name"]
    recorded = frame[value_column].map(lambda value: _number(value, decimal_comma))
    frame["_true_value"] = recorded - float(value_config["calibration_offset"])
    frame["_temperature"] = frame["inverter_temperature_C"].map(
        lambda value: _number(value, decimal_comma)
    )

    frame["_utc_time"] = (
        frame["_local_time"].dt.tz_localize(timezone).dt.tz_convert("UTC")
    )
    valid = (
        (frame["_utc_time"] >= UTC_START)
        & (frame["_utc_time"] < UTC_END)
        & frame["_true_value"].notna()
        & (frame["_true_value"] >= 0)
    )

    for start, end in COMPLETED_MAINTENANCE.get(farm_id, []):
        valid &= ~(
            (frame["_local_time"] >= start) & (frame["_local_time"] < end)
        )

    # There are no >85 C events in these exports, but retain the report's
    # shutdown protocol in the calculation.
    for spike in frame.loc[frame["_temperature"] > 85.0, "_utc_time"]:
        valid &= ~(
            (frame["_utc_time"] > spike)
            & (frame["_utc_time"] <= spike + pd.Timedelta(minutes=45))
        )

    sensor = calibration["sensor_info"]
    unit_factor = {
        "wh": 0.001,
        "kwh": 1.0,
        "mwh": 1000.0,
        "btu": 0.00029307107,
        "kw": 1.0,
    }[sensor["unit"].casefold()]
    total = frame.loc[valid, "_true_value"].sum() * unit_factor
    if sensor["reading_type"].casefold() == "power":
        total *= sampling_hours

    return int(round(float(total)))


def answer() -> dict[str, int]:
    calibrations = _calibrations()
    return {
        farm_id: _farm_total(farm_id, timezone, calibrations[farm_id])
        for farm_id, timezone in _registered_farms()
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w") as file:
        json.dump(answer(), file, default=list)
